def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    last_my, last_opp = history[-1]
    prev_my = history[-2][0]

    opp_d = 0
    matches = 0
    punished = 0
    unpunished = 0
    for i in range(n):
        a, b = history[i]
        if b == 'D':
            opp_d += 1
        if i > 0:
            if b == history[i - 1][0]:
                matches += 1
            if history[i - 1][0] == 'D':
                if b == 'D':
                    punished += 1
                else:
                    unpunished += 1

    recent_len = 10 if n >= 10 else n
    recent_d = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_d += 1

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break

    mirror = matches / float(max(1, n - 1))
    recent_rate = recent_d / float(recent_len)
    coop_rate = opp_d / float(n)

    hostile = n >= 10 and (opp_d >= n - opp_d or recent_d >= 6)
    if hostile:
        if last_opp == 'C' and recent_rate < 0.25 and rng.random() < 0.07:
            return 'C'
        return 'D'

    if opp_d == 0:
        if last_my == 'D':
            return 'D'
        if n > 70 and rng.random() < 0.03:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if prev_my == 'D':
            if recent_d >= 4 and streak_d >= 3:
                return 'D'
            return 'C'

        if last_my == 'D':
            if recent_d <= 2 and streak_d <= 3:
                return 'C'
            if recent_d >= 5:
                return 'D'
            if rng.random() < 0.35:
                return 'C'
            return 'D'

        if streak_d == 1 and coop_rate < 0.3 and rng.random() < 0.7:
            return 'C'
        if streak_d == 1 and coop_rate < 0.15:
            return 'C'
        return 'D'

    if last_my == 'D':
        if unpunished >= 2 and punished == 0:
            return 'D'
        if unpunished > punished and recent_rate < 0.2 and rng.random() < 0.5:
            return 'D'
        if mirror < 0.55 and recent_rate < 0.25 and rng.random() < 0.35:
            return 'D'
        return 'C'

    if mirror < 0.55 and opp_d > 0 and recent_d <= 2 and rng.random() < 0.12:
        return 'D'

    if n > 90 and coop_rate < 0.25 and rng.random() < 0.12:
        return 'D'

    return 'C'
